local function read_file(path)
  local f = assert(io.open(path, "rb"))
  local s = f:read("*a")
  f:close()
  return s
end

add("bn_mod against oracle vectors", function()
  for i, v in ipairs(MOD_VECTORS) do
    eq(crypto._bn_mod_hex(v.a, v.n), v.r, "vector " .. i)
  end
end)

add("rsa_verify accepts an openssl signature", function()
  local n_hex = string.match(read_file("tests/fixtures/test_modulus.txt"), "%x+")
  local sig = read_file("tests/fixtures/rsa_sig_good.bin")
  local msg = read_file("tests/fixtures/rsa_msg.txt")
  eq(crypto.rsa_verify(n_hex, sig, msg), true)
end)

add("rsa_verify rejects tampering", function()
  local n_hex = string.match(read_file("tests/fixtures/test_modulus.txt"), "%x+")
  local sig = read_file("tests/fixtures/rsa_sig_good.bin")
  local msg = read_file("tests/fixtures/rsa_msg.txt")

  eq(crypto.rsa_verify(n_hex, sig, msg .. "x"), false, "tampered message")
  local flipped = string.char(bit.bxor(string.byte(sig, 100), 1))
  local badsig = string.sub(sig, 1, 99) .. flipped .. string.sub(sig, 101)
  eq(crypto.rsa_verify(n_hex, badsig, msg), false, "tampered signature")
  eq(crypto.rsa_verify(n_hex, string.sub(sig, 2), msg), false, "short signature")
  eq(crypto.rsa_verify(n_hex, sig .. "\0", msg), false, "long signature")
  eq(crypto.rsa_verify(n_hex, string.rep("\255", 256), msg), false,
    "signature >= modulus")
  -- wrong key: modulus with two hex digits swapped is a different number
  local wrong = string.sub(n_hex, 1, 10)
    .. string.sub(n_hex, 12, 12) .. string.sub(n_hex, 11, 11)
    .. string.sub(n_hex, 13)
  if wrong ~= n_hex then
    eq(crypto.rsa_verify(wrong, sig, msg), false, "wrong modulus")
  end
end)

local failures = 0
for _, test in ipairs(tests) do
  local ok, err = pcall(test.fn)
  if not ok then
    failures = failures + 1
    io.stderr:write("FAIL ", test.name, "\n", tostring(err), "\n")
  end
end
if failures > 0 then os.exit(1) end
